insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('6823bfaf-84d5-4ac7-a588-57daa7d030cc', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', null, 'topic'::public.curated_course_node_type, 'Archaeology as Anthropology: Questions, Evidence, and Deep Time', 'Understand archaeology as the study of human life through material traces, long-term change, and disciplined inference from incomplete evidence.', 0),
  ('ee5f3201-5031-4043-a3e0-6c5c8d24ea38', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', '6823bfaf-84d5-4ac7-a588-57daa7d030cc', 'subtopic'::public.curated_course_node_type, 'Archaeological questions and scales of analysis', 'This subtopic clarifies what archaeology can ask that texts or living memory cannot, from household practices to migrations, economies, and deep-time change.', 0),
  ('ff6c6df7-d5de-42fa-8042-66a400c19a0a', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', 'ee5f3201-5031-4043-a3e0-6c5c8d24ea38', 'concept'::public.curated_course_node_type, 'Research questions, hypotheses, and interpretive limits', null, 0),
  ('32513655-0789-48ae-bcd3-1f1c068c5ff8', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', 'ee5f3201-5031-4043-a3e0-6c5c8d24ea38', 'concept'::public.curated_course_node_type, 'Sites, assemblages, features, ecofacts, landscapes, and regions', null, 1),
  ('accc7a55-819b-4645-9f11-53413c02ec83', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', 'ee5f3201-5031-4043-a3e0-6c5c8d24ea38', 'concept'::public.curated_course_node_type, 'Deep time, historical periods, and comparative temporal scales', null, 2),
  ('cc1d2c8e-7b94-43aa-bd13-130a9d452015', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', '6823bfaf-84d5-4ac7-a588-57daa7d030cc', 'subtopic'::public.curated_course_node_type, 'Material evidence and inference', 'Students learn how archaeologists move carefully from physical traces to claims about behavior, social life, and historical process.', 1),
  ('44b7b757-4324-4d6a-b743-1d37fe73ba99', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', 'cc1d2c8e-7b94-43aa-bd13-130a9d452015', 'concept'::public.curated_course_node_type, 'Context, association, formation processes, and taphonomy', null, 0),
  ('10f15563-34b8-4e23-8b8f-2617b7dc0fb2', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', 'cc1d2c8e-7b94-43aa-bd13-130a9d452015', 'concept'::public.curated_course_node_type, 'Analogy, middle-range theory, and experimental reasoning', null, 1),
  ('dbd797f4-b0ad-46b8-90e4-d53557ebc176', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', 'cc1d2c8e-7b94-43aa-bd13-130a9d452015', 'concept'::public.curated_course_node_type, 'Uncertainty, sampling bias, preservation bias, and evidentiary gaps', null, 2),
