  ('0bc35325-239b-4196-986a-bdf53f8b9070', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', '4e781376-f077-404a-9801-170608a55fcc', 'concept'::public.curated_course_node_type, 'Cultural, biological, linguistic, and archaeological anthropology', null, 0),
  ('8dd825d4-5ecb-49bb-aeab-8247e45b04af', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', '4e781376-f077-404a-9801-170608a55fcc', 'concept'::public.curated_course_node_type, 'Connections to environmental science, geoscience, and museum studies', null, 1),
  ('5469c41a-1a9f-4074-bb2f-954c8320987b', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', '4e781376-f077-404a-9801-170608a55fcc', 'concept'::public.curated_course_node_type, 'Archaeology in public, applied, academic, and CRM careers', null, 2),
  ('02601979-ae95-4536-addb-be20952447ce', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', null, 'topic'::public.curated_course_node_type, 'History of Archaeology and Archaeological Theory', 'Trace how archaeological interpretation changed from antiquarian collecting to scientific, social, Indigenous, feminist, and decolonial approaches.', 1),
  ('ea173e1c-fe23-40f7-8335-9feb6e84418d', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', '02601979-ae95-4536-addb-be20952447ce', 'subtopic'::public.curated_course_node_type, 'Antiquarianism, culture history, and classification', 'This subtopic explains the early roots of archaeology and why typology, chronology, and culture-area thinking became so influential.', 0),
  ('a56c22f0-7350-4088-98b6-167c27ef9186', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', 'ea173e1c-fe23-40f7-8335-9feb6e84418d', 'concept'::public.curated_course_node_type, 'Collectors, museums, colonial expeditions, and early excavation', null, 0),
  ('0c292cc6-7e26-4319-ba4d-b3d8f892364b', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', 'ea173e1c-fe23-40f7-8335-9feb6e84418d', 'concept'::public.curated_course_node_type, 'Typology, seriation, culture areas, and diffusion', null, 1),
  ('5da89966-6f7f-4581-8335-3fae966260fd', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', 'ea173e1c-fe23-40f7-8335-9feb6e84418d', 'concept'::public.curated_course_node_type, 'Strengths and limits of culture-historical explanation', null, 2),
  ('cc393c47-4659-4ae1-826f-8706ec06da73', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', '02601979-ae95-4536-addb-be20952447ce', 'subtopic'::public.curated_course_node_type, 'Processual and postprocessual archaeology', 'Students compare archaeology as explanatory social science with approaches that emphasize meaning, agency, identity, and power.', 1),
  ('66a467b2-ef97-499d-a42d-6b8aa9a1b773', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', 'cc393c47-4659-4ae1-826f-8706ec06da73', 'concept'::public.curated_course_node_type, 'Systems theory, ecology, adaptation, and hypothesis testing', null, 0),
  ('f301362a-cb15-484c-bf0c-4b5b879887bc', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', 'cc393c47-4659-4ae1-826f-8706ec06da73', 'concept'::public.curated_course_node_type, 'Symbolic, interpretive, agency-centered, and practice approaches', null, 1),
  ('1280ae0d-b4a2-42bc-a5da-6feee529ce0c', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', 'cc393c47-4659-4ae1-826f-8706ec06da73', 'concept'::public.curated_course_node_type, 'Debates over objectivity, explanation, and interpretation', null, 2),
  ('6318616b-b5cf-4f8e-a283-a4215bc2d4d4', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', '02601979-ae95-4536-addb-be20952447ce', 'subtopic'::public.curated_course_node_type, 'Indigenous, feminist, Black, and decolonial archaeologies', 'This section centers critiques that ask who controls questions, collections, narratives, ancestral remains, and public authority.', 2),
  ('7831acc0-30ff-46c5-9912-d975ab919ce5', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', '6318616b-b5cf-4f8e-a283-a4215bc2d4d4', 'concept'::public.curated_course_node_type, 'Community-based research and collaborative authority', null, 0),
  ('457a9dd4-2a77-44a3-ac17-1f1b34e41b0e', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', '6318616b-b5cf-4f8e-a283-a4215bc2d4d4', 'concept'::public.curated_course_node_type, 'Gender, race, labor, colonialism, and standpoint in interpretation', null, 1),
  ('79d85bed-1c48-4257-9995-9577ded862f5', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', '6318616b-b5cf-4f8e-a283-a4215bc2d4d4', 'concept'::public.curated_course_node_type, 'Repatriation, restorative practice, and anti-extractive research', null, 2),
  ('e763653e-62f0-4276-b58b-1cc6267ab85a', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', null, 'topic'::public.curated_course_node_type, 'Research Design, Ethics, Law, and Cultural Heritage Stewardship', 'Plan archaeological research that is rigorous, lawful, ethical, collaborative, and accountable to descendant and stakeholder communities.', 2),
  ('1074836e-bdad-4a81-a103-5466550bc654', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', 'e763653e-62f0-4276-b58b-1cc6267ab85a', 'subtopic'::public.curated_course_node_type, 'Research design and project planning', 'Students learn how strong archaeology begins before the trench: with questions, sampling logic, permissions, and a preservation plan.', 0),
  ('9e76fb26-1f24-47e1-a398-40c479d645a6', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', '1074836e-bdad-4a81-a103-5466550bc654', 'concept'::public.curated_course_node_type, 'Problem statements, background research, and expected evidence', null, 0),
  ('afbdbb6d-d96a-41d5-b63d-f72251b9a73b', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', '1074836e-bdad-4a81-a103-5466550bc654', 'concept'::public.curated_course_node_type, 'Sampling strategy, methods selection, budget, personnel, and timeline', null, 1),
  ('7d6639a6-6874-4be2-85b4-0078af45eed0', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', '1074836e-bdad-4a81-a103-5466550bc654', 'concept'::public.curated_course_node_type, 'Permits, collections management, publication, and data archiving plans', null, 2),
  ('28e8a91b-b6e2-4a61-adc0-25c3dfe7964d', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', 'e763653e-62f0-4276-b58b-1cc6267ab85a', 'subtopic'::public.curated_course_node_type, 'Professional ethics and responsibilities', 'This subtopic frames archaeology as stewardship rather than treasure hunting, with duties to people, places, records, and future researchers.', 1),
  ('ecd63949-9e72-4361-b957-18e9ec4fb80c', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', '28e8a91b-b6e2-4a61-adc0-25c3dfe7964d', 'concept'::public.curated_course_node_type, 'SAA principles, site protection, looting, and illicit antiquities', null, 0),
  ('30687701-c9a6-460d-b068-167eb06c993b', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', '28e8a91b-b6e2-4a61-adc0-25c3dfe7964d', 'concept'::public.curated_course_node_type, 'Human remains, sacred objects, confidentiality, and sensitive data', null, 1),
  ('0005daa5-c351-41eb-acd5-265940e80fcd', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', '28e8a91b-b6e2-4a61-adc0-25c3dfe7964d', 'concept'::public.curated_course_node_type, 'Responsible communication, public trust, and avoiding harm', null, 2),
  ('f8559880-0265-4dca-9257-f36aa21c56ea', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', 'e763653e-62f0-4276-b58b-1cc6267ab85a', 'subtopic'::public.curated_course_node_type, 'Heritage law, repatriation, and sovereignty', 'Students study the legal and political frameworks that govern excavation, collections, consultation, and return of cultural materials.', 2),
  ('e5b97802-7a9b-4c0a-b0c5-b8876f6965f1', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', 'f8559880-0265-4dca-9257-f36aa21c56ea', 'concept'::public.curated_course_node_type, 'NAGPRA, NHPA Section 106, ARPA, state historic preservation, and tribal consultation', null, 0),
  ('49d8ffac-b4ad-4c92-82d9-ab33efc86624', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', 'f8559880-0265-4dca-9257-f36aa21c56ea', 'concept'::public.curated_course_node_type, 'UNESCO heritage frameworks and international antiquities debates', null, 1),
  ('e00ae7da-ec7d-43b5-b616-1a38a56dff8f', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', 'f8559880-0265-4dca-9257-f36aa21c56ea', 'concept'::public.curated_course_node_type, 'Data sovereignty, intellectual property, and community review', null, 2),
  ('6a34d30a-1fdd-4147-9488-8c11ea244853', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', null, 'topic'::public.curated_course_node_type, 'Survey, Site Discovery, Mapping, GIS, and Remote Sensing', 'Develop the ability to find, map, and interpret archaeological sites and landscapes using pedestrian, geospatial, and noninvasive methods.', 3);
