  ('2a8d2c1c-60e3-4817-9c9d-b4b6a630671d', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', '9bfe29bb-b673-4938-a455-b3dbefb9400b', 'concept'::public.curated_course_node_type, 'Ground-truthing, false positives, and method selection by site condition', null, 2),
