  ('5c0ba751-7cc2-4165-b8dc-6010237a7237', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', 'fe8e1977-d88b-4f6b-8fca-8be079c4393b', 'subtopic'::public.curated_course_node_type, 'Excavation strategy and sampling', 'Students learn why excavation is destructive and therefore must be designed to answer questions while preserving maximum information.', 0),
