  ('c39a0246-6966-41ae-9811-2540299f1522', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', 'da142385-360d-4cb4-b0c7-7acd6ffc0192', 'concept'::public.curated_course_node_type, 'Bagging, labeling, provenience control, chain of custody, and metadata', null, 1),
  ('9a78b592-063f-489b-b4a9-861592c2e863', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', 'da142385-360d-4cb4-b0c7-7acd6ffc0192', 'concept'::public.curated_course_node_type, 'Daily interpretation, error checking, and field database management', null, 2),
