  ('67db0ae9-9c29-4e80-9acc-3bc49623b80b', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', '39832893-bfb1-4f95-8387-7c65079b0e04', 'concept'::public.curated_course_node_type, 'Stratigraphy, typology, seriation, cross-dating, and terminus post quem', null, 0),
