  ('03909395-1874-475d-9ab5-04344d53c71c', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', '39832893-bfb1-4f95-8387-7c65079b0e04', 'concept'::public.curated_course_node_type, 'Association, residuality, intrusion, and mixed deposits', null, 2),
