  ('630de635-7a21-4818-b71d-cf33222d3b3c', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', '291edf44-65f6-4a78-af15-6e6d97b77cff', 'concept'::public.curated_course_node_type, 'Radiocarbon, dendrochronology, archaeomagnetism, OSL, TL, uranium-series, and potassium-argon', null, 0),
