  ('e7b5cace-1d66-4233-9dec-c53d99548af1', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', '998a7e52-2855-4ad9-a31e-fa1475062499', 'concept'::public.curated_course_node_type, 'Radiocarbon calibration curves and calendar-year ranges', null, 0),
  ('7a44ec3e-c28b-49ab-809f-c33ecdb23d54', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', '998a7e52-2855-4ad9-a31e-fa1475062499', 'concept'::public.curated_course_node_type, 'Bayesian priors, phases, boundaries, and outlier models', null, 1),
