  ('3242b745-6996-430e-8371-bdccb3725d74', 'f0a1b2c3-4d5e-4a20-9b90-0c1d2e3f4a00', '616fed86-90bf-4f1d-8555-4f8e6b94a77f', 'subtopic'::public.curated_course_node_type, 'Isotopes, diet, mobility, and ancient DNA', 'This subtopic introduces biomolecular methods that can transform archaeological questions when used carefully.', 1),
