update public.learning_paths
set
  title = 'Archaeology',
  goal = 'Archaeology',
  summary = 'This course treats archaeology as an evidence-driven, ethically accountable study of human lives through material remains. It begins with archaeological questions and theory, moves through field, laboratory, dating, digital, and interpretive methods, and ends with applied heritage practice, CRM, public communication, and a capstone research product.',
  data = $archjson${"slug": "archaeology", "title": "Archaeology", "description": "This course treats archaeology as an evidence-driven, ethically accountable study of human lives through material remains. It begins with archaeological questions and theory, moves through field, laboratory, dating, digital, and interpretive methods, and ends with applied heritage practice, CRM, public communication, and a capstone research product.", "topics": [{"id": "6823bfaf-84d5-4ac7-a588-57daa7d030cc", "type": "topic", "title": "Archaeology as Anthropology: Questions, Evidence, and Deep Time", "description": "Understand archaeology as the study of human life through material traces, long-term change, and disciplined inference from incomplete evidence.", "children": [{"id": "ee5f3201-5031-4043-a3e0-6c5c8d24ea38", "type": "subtopic", "title": "Archaeological questions and scales of analysis", "children": [{"id": "ff6c6df7-d5de-42fa-8042-66a400c19a0a", "type": "concept", "title": "Research questions, hypotheses, and interpretive limits"}, {"id": "32513655-0789-48ae-bcd3-1f1c068c5ff8", "type": "concept", "title": "Sites, assemblages, features, ecofacts, landscapes, and regions"}, {"id": "accc7a55-819b-4645-9f11-53413c02ec83", "type": "concept", "title": "Deep time, historical periods, and comparative temporal scales"}], "description": "This subtopic clarifies what archaeology can ask that texts or living memory cannot, from household practices to migrations, economies, and deep-time change."}, {"id": "cc1d2c8e-7b94-43aa-bd13-130a9d452015", "type": "subtopic", "title": "Material evidence and inference", "children": [{"id": "44b7b757-4324-4d6a-b743-1d37fe73ba99", "type": "concept", "title": "Context, association, formation processes, and taphonomy"}, {"id": "10f15563-34b8-4e23-8b8f-2617b7dc0fb2", "type": "concept", "title": "Analogy, middle-range theory, and experimental reasoning"}, {"id": "dbd797f4-b0ad-46b8-90e4-d53557ebc176", "type": "concept", "title": "Uncertainty, sampling bias, preservation bias, and evidentiary gaps"}], "description": "Students learn how archaeologists move carefully from physical traces to claims about behavior, social life, and historical process."}, {"id": "4e781376-f077-404a-9801-170608a55fcc", "type": "subtopic", "title": "Four-field and interdisciplinary connections", "children": [{"id": "0bc35325-239b-4196-986a-bdf53f8b9070", "type": "concept", "title": "Cultural, biological, linguistic, and archaeological anthropology"}, {"id": "8dd825d4-5ecb-49bb-aeab-8247e45b04af", "type": "concept", "title": "Connections to environmental science, geoscience, and museum studies"}, {"id": "5469c41a-1a9f-4074-bb2f-954c8320987b", "type": "concept", "title": "Archaeology in public, applied, academic, and CRM careers"}], "description": "The course places archaeology within anthropology while showing how it draws from history, geology, biology, chemistry, geography, and heritage studies."}]}, {"id": "02601979-ae95-4536-addb-be20952447ce", "type": "topic", "title": "History of Archaeology and Archaeological Theory", "description": "Trace how archaeological interpretation changed from antiquarian collecting to scientific, social, Indigenous, feminist, and decolonial approaches.", "children": [{"id": "ea173e1c-fe23-40f7-8335-9feb6e84418d", "type": "subtopic", "title": "Antiquarianism, culture history, and classification", "children": [{"id": "a56c22f0-7350-4088-98b6-167c27ef9186", "type": "concept", "title": "Collectors, museums, colonial expeditions, and early excavation"}, {"id": "0c292cc6-7e26-4319-ba4d-b3d8f892364b", "type": "concept", "title": "Typology, seriation, culture areas, and diffusion"}, {"id": "5da89966-6f7f-4581-8335-3fae966260fd", "type": "concept", "title": "Strengths and limits of culture-historical explanation"}], "description": "This subtopic explains the early roots of archaeology and why typology, chronology, and culture-area thinking became so influential."}, {"id": "cc393c47-4659-4ae1-826f-8706ec06da73", "type": "subtopic", "title": "Processual and postprocessual archaeology", "children": [{"id": "66a467b2-ef97-499d-a42d-6b8aa9a1b773", "type": "concept", "title": "Systems theory, ecology, adaptation, and hypothesis testing"}, {"id": "f301362a-cb15-484c-bf0c-4b5b879887bc", "type": "concept", "title": "Symbolic, interpretive, agency-centered, and practice approaches"}, {"id": "1280ae0d-b4a2-42bc-a5da-6feee529ce0c", "type": "concept", "title": "Debates over objectivity, explanation, and interpretation"}], "description": "Students compare archaeology as explanatory social science with approaches that emphasize meaning, agency, identity, and power."}, {"id": "6318616b-b5cf-4f8e-a283-a4215bc2d4d4", "type": "subtopic", "title": "Indigenous, feminist, Black, and decolonial archaeologies", "children": [{"id": "7831acc0-30ff-46c5-9912-d975ab919ce5", "type": "concept", "title": "Community-based research and collaborative authority"}, {"id": "457a9dd4-2a77-44a3-ac17-1f1b34e41b0e", "type": "concept", "title": "Gender, race, labor, colonialism, and standpoint in interpretation"}, {"id": "79d85bed-1c48-4257-9995-9577ded862f5", "type": "concept", "title": "Repatriation, restorative practice, and anti-extractive research"}], "description": "This section centers critiques that ask who controls questions, collections, narratives, ancestral remains, and public authority."}]}, {"id": "e763653e-62f0-4276-b58b-1cc6267ab85a", "type": "topic", "title": "Research Design, Ethics, Law, and Cultural Heritage Stewardship", "description": "Plan archaeological research that is rigorous, lawful, ethical, collaborative, and accountable to descendant and stakeholder communities.", "children": [{"id": "1074836e-bdad-4a81-a103-5466550bc654", "type": "subtopic", "title": "Research design and project planning", "children": [{"id": "9e76fb26-1f24-47e1-a398-40c479d645a6", "type": "concept", "title": "Problem statements, background research, and expected evidence"}, {"id": "afbdbb6d-d96a-41d5-b63d-f72251b9a73b", "type": "concept", "title": "Sampling strategy, methods selection, budget, personnel, and timeline"}, {"id": "7d6639a6-6874-4be2-85b4-0078af45eed0", "type": "concept", "title": "Permits, collections management, publication, and data archiving plans"}], "description": "Students learn how strong archaeology begins before the trench: with questions, sampling logic, permissions, and a preservation plan."}, {"id": "28e8a91b-b6e2-4a61-adc0-25c3dfe7964d", "type": "subtopic", "title": "Professional ethics and responsibilities", "children": [{"id": "ecd63949-9e72-4361-b957-18e9ec4fb80c", "type": "concept", "title": "SAA principles, site protection, looting, and illicit antiquities"}, {"id": "30687701-c9a6-460d-b068-167eb06c993b", "type": "concept", "title": "Human remains, sacred objects, confidentiality, and sensitive data"}, {"id": "0005daa5-c351-41eb-acd5-265940e80fcd", "type": "concept", "title": "Responsible communication, public trust, and avoiding harm"}], "description": "This subtopic frames archaeology as stewardship rather than treasure hunting, with duties to people, places, records, and future researchers."}, {"id": "f8559880-0265-4dca-9257-f36aa21c56ea", "type": "subtopic", "title": "Heritage law, repatriation, and sovereignty", "children": [{"id": "e5b97802-7a9b-4c0a-b0c5-b8876f6965f1", "type": "concept", "title": "NAGPRA, NHPA Section 106, ARPA, state historic preservation, and tribal consultation"}, {"id": "49d8ffac-b4ad-4c92-82d9-ab33efc86624", "type": "concept", "title": "UNESCO heritage frameworks and international antiquities debates"}, {"id": "e00ae7da-ec7d-43b5-b616-1a38a56dff8f", "type": "concept", "title": "Data sovereignty, intellectual property, and community review"}], "description": "Students study the legal and political frameworks that govern excavation, collections, consultation, and return of cultural materials."}]}, {"id": "6a34d30a-1fdd-4147-9488-8c11ea244853", "type": "topic", "title": "Survey, Site Discovery, Mapping, GIS, and Remote Sensing", "description": "Develop the ability to find, map, and interpret archaeological sites and landscapes using pedestrian, geospatial, and noninvasive methods.", "children": [{"id": "fdfcbca9-30cc-41fe-b922-24ae428a6bf8", "type": "subtopic", "title": "Pedestrian survey and site discovery", "children": [{"id": "1d1c1dfe-5067-4591-9997-c231d7f16ee1", "type": "concept", "title": "Transects, shovel tests, systematic sampling, and judgmental survey"}, {"id": "c62e63c1-0e3b-4a7e-b936-f2b1ee56d643", "type": "concept", "title": "Artifact scatters, site boundaries, visibility, and landform interpretation"}, {"id": "06c329b1-45df-436d-8657-b14dc4c8299d", "type": "concept", "title": "Survey forms, field notes, photographs, and GPS recording"}], "description": "This subtopic introduces the practical logic of locating archaeological remains across terrain while recording visibility and sampling conditions."}, {"id": "2974d311-4706-4f2a-97d3-7e0dbe1849d9", "type": "subtopic", "title": "Mapping, GIS, and spatial thinking", "children": [{"id": "da46c81b-48e6-48c8-a3e1-de54ef50a992", "type": "concept", "title": "Coordinate systems, GPS/GNSS, total station, and drone mapping basics"}, {"id": "285f6846-ff3b-4ab8-aefc-1fd578cc1db5", "type": "concept", "title": "Georeferencing, layers, buffers, viewsheds, and least-cost paths"}, {"id": "9860c673-7f71-40ea-895f-84e916f288ee", "type": "concept", "title": "Site distribution, catchment analysis, and landscape archaeology"}], "description": "Students learn to treat space as evidence, using maps to analyze movement, settlement, environment, and social organization."}, {"id": "9bfe29bb-b673-4938-a455-b3dbefb9400b", "type": "subtopic", "title": "Remote sensing and prospection", "children": [{"id": "fd25bded-598c-4c53-b067-3a5007f4cc06", "type": "concept", "title": "Aerial photography, satellite imagery, LiDAR, and photogrammetry"}, {"id": "dcc0a938-f3f0-4433-92b6-9c2ca37b9ba5", "type": "concept", "title": "Magnetometry, ground-penetrating radar, resistivity, and conductivity"}, {"id": "2a8d2c1c-60e3-4817-9c9d-b4b6a630671d", "type": "concept", "title": "Ground-truthing, false positives, and method selection by site condition"}], "description": "This section shows how archaeologists detect buried or large-scale features without immediate excavation."}]}, {"id": "fe8e1977-d88b-4f6b-8fca-8be079c4393b", "type": "topic", "title": "Excavation Strategy, Stratigraphy, Context, and Field Recording", "description": "Learn how excavation produces evidence through controlled removal, context recording, stratigraphic reasoning, and transparent documentation.", "children": [{"id": "5c0ba751-7cc2-4165-b8dc-6010237a7237", "type": "subtopic", "title": "Excavation strategy and sampling", "children": [{"id": "92e11d8d-d7fa-4853-b548-228d929d2595", "type": "concept", "title": "Test units, trenches, block excavation, open-area excavation, and rescue excavation"}, {"id": "2e7f9ed8-4f9a-4972-9298-84dcd9e9fc7f", "type": "concept", "title": "Arbitrary levels versus natural/cultural stratigraphy"}, {"id": "0c08a2d9-b9d3-4ba7-89a0-278b73052acf", "type": "concept", "title": "Sampling for artifacts, soil, flotation, residue, dating, and environmental evidence"}], "description": "Students learn why excavation is destructive and therefore must be designed to answer questions while preserving maximum information."}, {"id": "76ebf0ee-ff31-4401-afaf-a4c0e5896f32", "type": "subtopic", "title": "Stratigraphy and context", "children": [{"id": "cda1e008-0e79-4a94-a90d-aea19de5993b", "type": "concept", "title": "Law of superposition, interfaces, cuts, fills, and depositional events"}, {"id": "350ce33c-cd17-451d-821c-d561748d0bbd", "type": "concept", "title": "Harris matrix construction and sequence interpretation"}, {"id": "373e5ce3-ebc0-45e2-8e7c-ec9427fb53f2", "type": "concept", "title": "Site formation processes, disturbance, reuse, and bioturbation"}], "description": "This subtopic builds the core skill of reading deposits, cuts, fills, floors, features, and relationships in time."}, {"id": "da142385-360d-4cb4-b0c7-7acd6ffc0192", "type": "subtopic", "title": "Field recording and quality control", "children": [{"id": "952bd2c4-1093-478e-93cd-65d57ccb516c", "type": "concept", "title": "Context sheets, plan/profile drawings, photography, scales, and logs"}, {"id": "c39a0246-6966-41ae-9811-2540299f1522", "type": "concept", "title": "Bagging, labeling, provenience control, chain of custody, and metadata"}, {"id": "9a78b592-063f-489b-b4a9-861592c2e863", "type": "concept", "title": "Daily interpretation, error checking, and field database management"}], "description": "Students practice the documentation habits that make excavation evidence usable after the site is backfilled."}]}, {"id": "ef24c18a-6c35-4eec-bfe5-2bcfdb9719d7", "type": "topic", "title": "Chronology and Dating Methods", "description": "Build reliable timelines by combining relative dating, absolute dating, calibration, and critical interpretation of uncertainty.", "children": [{"id": "39832893-bfb1-4f95-8387-7c65079b0e04", "type": "subtopic", "title": "Relative dating and sequence building", "children": [{"id": "67db0ae9-9c29-4e80-9acc-3bc49623b80b", "type": "concept", "title": "Stratigraphy, typology, seriation, cross-dating, and terminus post quem"}, {"id": "b588df1b-5c2b-423f-9d86-3311f1d86048", "type": "concept", "title": "Ceramic, lithic, architectural, and stylistic sequences"}, {"id": "03909395-1874-475d-9ab5-04344d53c71c", "type": "concept", "title": "Association, residuality, intrusion, and mixed deposits"}], "description": "This subtopic explains how archaeologists order events even before absolute dates are available."}, {"id": "291edf44-65f6-4a78-af15-6e6d97b77cff", "type": "subtopic", "title": "Absolute and chronometric methods", "children": [{"id": "630de635-7a21-4818-b71d-cf33222d3b3c", "type": "concept", "title": "Radiocarbon, dendrochronology, archaeomagnetism, OSL, TL, uranium-series, and potassium-argon"}, {"id": "0a886bbd-242c-4f19-bdfd-e725670421c1", "type": "concept", "title": "Sample selection, contamination, reservoir effects, and pretreatment"}, {"id": "2cc5d2a0-85a2-47e2-90eb-789f17589f1a", "type": "concept", "title": "Precision, accuracy, error ranges, and reporting conventions"}], "description": "Students learn the principles, sample requirements, and interpretive limits of major dating techniques."}, {"id": "998a7e52-2855-4ad9-a31e-fa1475062499", "type": "subtopic", "title": "Calibration and Bayesian chronology", "children": [{"id": "e7b5cace-1d66-4233-9dec-c53d99548af1", "type": "concept", "title": "Radiocarbon calibration curves and calendar-year ranges"}, {"id": "7a44ec3e-c28b-49ab-809f-c33ecdb23d54", "type": "concept", "title": "Bayesian priors, phases, boundaries, and outlier models"}, {"id": "14f1c405-8ace-4686-824c-4e78d5d4ed91", "type": "concept", "title": "Communicating uncertainty in site reports and public interpretation"}], "description": "This section introduces modern chronological modeling so students can move beyond single dates toward defensible sequences."}]}, {"id": "6281388d-a231-4826-a0be-5e89605113bd", "type": "topic", "title": "Material Culture Analysis: Lithics, Ceramics, Metals, Glass, and Architecture", "description": "Analyze artifacts as evidence of technology, labor, exchange, identity, daily practice, and social organization.", "children": [{"id": "251b8934-7152-4014-add0-05c5a69221ab", "type": "subtopic", "title": "Lithic and ceramic analysis", "children": [{"id": "7a981543-8a99-4872-b472-2f6695903059", "type": "concept", "title": "Raw material sourcing, reduction sequences, tools, debitage, and microwear"}, {"id": "39497d46-f861-457b-9474-9ead5783c352", "type": "concept", "title": "Clay, temper, forming, firing, decoration, function, and vessel use"}, {"id": "6688ea99-5c84-4bbd-8e5d-4c0bd8b81967", "type": "concept", "title": "Typology, attribute analysis, refitting, and assemblage comparison"}], "description": "Students learn two cornerstone artifact classes and how production debris, form, and use reveal behavior."}, {"id": "6778df89-0ae3-4a73-8178-9e8d8fa1da22", "type": "subtopic", "title": "Metals, glass, architecture, and built environments", "children": [{"id": "74905459-f879-45e5-ab98-423e6deef093", "type": "concept", "title": "Metallurgy, slag, casting, forging, alloys, and corrosion"}, {"id": "f7408c61-6950-4191-a68f-384d2aca7dec", "type": "concept", "title": "Glass production, beads, containers, exchange, and compositional analysis"}, {"id": "5aa98d9f-fc1b-4b90-a3ed-58eaf64404a6", "type": "concept", "title": "Domestic architecture, public buildings, roads, walls, and activity areas"}], "description": "This subtopic expands artifact analysis into technologies and structures that reveal craft, trade, status, and spatial organization."}, {"id": "512293d7-be86-4789-b4d8-fdf02cf8d127", "type": "subtopic", "title": "Consumption, exchange, and meaning", "children": [{"id": "b543a469-691f-4d57-af99-7370e1a76292", "type": "concept", "title": "Household economies, craft specialization, market and nonmarket exchange"}, {"id": "d89f7efd-1d4c-4fe8-9bd3-0aee58eb6459", "type": "concept", "title": "Style, identity, status, ritual use, heirlooms, and object biographies"}, {"id": "f8fc581b-eb17-49de-8933-93571193eb15", "type": "concept", "title": "Discard patterns, reuse, repair, recycling, and deposition"}], "description": "Students connect objects to the social worlds that made, moved, repaired, valued, and discarded them."}]}, {"id": "616fed86-90bf-4f1d-8555-4f8e6b94a77f", "type": "topic", "title": "Bioarchaeology, Human Osteology, Isotopes, and Ancient DNA", "description": "Study human remains ethically as evidence of health, diet, mobility, kinship, violence, demography, and lived experience.", "children": [{"id": "95e5c454-8728-4ea8-9880-bfcd3ac4a377", "type": "subtopic", "title": "Human osteology and paleopathology", "children": [{"id": "8eeadfed-97ab-4ee9-b6dd-41b7f9acf968", "type": "concept", "title": "Bone identification, age, sex estimation, stature, and biological profile"}, {"id": "26c71a0d-3757-4de0-8aa1-16a5f65ab6e8", "type": "concept", "title": "Trauma, disease, dental health, stress markers, and activity indicators"}, {"id": "97e23643-ea11-4d85-81b5-d6bdabcea730", "type": "concept", "title": "Population-level inference and uncertainty in skeletal interpretation"}], "description": "Students learn what skeletal evidence can and cannot reveal about individual bodies and population histories."}, {"id": "3242b745-6996-430e-8371-bdccb3725d74", "type": "subtopic", "title": "Isotopes, diet, mobility, and ancient DNA", "children": [{"id": "524de513-9172-410c-a8cd-523a6089096f", "type": "concept", "title": "Carbon, nitrogen, oxygen, strontium, sulfur, and lead isotope applications"}, {"id": "5d0ce4aa-a9e4-4ebd-a9f6-56ab5e13878c", "type": "concept", "title": "Ancient DNA sampling, contamination, ancestry, kinship, and pathogen studies"}, {"id": "cd976a9b-af55-4b86-8b28-450a59502453", "type": "concept", "title": "Integrating biomolecular evidence with context, culture, and ethics"}], "description": "This subtopic introduces biomolecular methods that can transform archaeological questions when used carefully."}, {"id": "bd4673d5-7355-4155-861b-e15a3cb8a8f0", "type": "subtopic", "title": "Ethics of ancestral remains", "children": [{"id": "dc87a3f2-d398-4873-9879-7651175216e2", "type": "concept", "title": "Consultation, consent, reburial, repatriation, and descendant authority"}, {"id": "0ab7b76b-9497-4573-ada9-bd0085f51b32", "type": "concept", "title": "Museums, legacy collections, destructive sampling, and benefit sharing"}, {"id": "409fb553-3c9c-403f-9772-bf46bba76480", "type": "concept", "title": "Avoiding biological determinism and sensationalized narratives"}], "description": "Students examine why human remains require special legal, cultural, and ethical care."}]}, {"id": "145a0959-1279-4dff-86be-d26ba541cba3", "type": "topic", "title": "Environmental Archaeology, Zooarchaeology, Paleoethnobotany, and Geoarchaeology", "description": "Reconstruct past environments, subsistence, climate relationships, and human ecological impact through biological and geological evidence.", "children": [{"id": "ec09ec04-9f06-40d1-9384-155fdcc5b3da", "type": "subtopic", "title": "Zooarchaeology and paleoethnobotany", "children": [{"id": "8b1dff3a-2d50-4892-a358-f0d2ef5c6da7", "type": "concept", "title": "Taxonomy, skeletal elements, MNI/NISP, butchery, burning, and taphonomy"}, {"id": "83b9c0fa-d4bf-4715-8caf-c3968c7d6b6f", "type": "concept", "title": "Seeds, wood charcoal, phytoliths, starch, pollen, flotation, and macroremains"}, {"id": "459f6173-17a3-448a-924e-acc7e1f5c737", "type": "concept", "title": "Foraging, farming, herding, fishing, feasting, and foodways"}], "description": "Students learn how animal and plant remains reveal diet, domestication, seasonality, trade, ritual, and environmental change."}, {"id": "8a432969-20dc-4791-bc73-ff370279f4e5", "type": "subtopic", "title": "Geoarchaeology and sediments", "children": [{"id": "ebc00c19-4955-415d-85f3-37e6002886c6", "type": "concept", "title": "Soils, stratigraphy, micromorphology, geomorphology, and sediment analysis"}, {"id": "2e82a6b6-3d63-4f48-90fe-712c777c608c", "type": "concept", "title": "Floodplains, caves, coastlines, dunes, terraces, and urban deposits"}, {"id": "c49b05a9-af4c-4557-9e72-71effa707360", "type": "concept", "title": "Formation processes, preservation environments, and disturbance"}], "description": "This subtopic uses earth-science tools to understand site formation, landscape change, and depositional history."}, {"id": "1f8a77a4-7ae9-41dd-9d79-ed9ebe1942bc", "type": "subtopic", "title": "Climate, environment, and human adaptation", "children": [{"id": "3a29d0e6-e0d9-44f7-b9b8-e13bb334ec37", "type": "concept", "title": "Paleoclimate proxies, drought, sea-level change, and environmental stress"}, {"id": "1ef3d272-b7ee-4382-bc04-437526949a74", "type": "concept", "title": "Domestication, land use, fire, irrigation, deforestation, and sustainability"}, {"id": "112071b1-78c8-47e7-aab6-54ccd6cb0f36", "type": "concept", "title": "Avoiding environmental determinism in archaeological explanation"}], "description": "Students evaluate claims about climate and collapse with attention to scale, resilience, and social choice."}]}, {"id": "1613b508-8df1-4acd-84e7-55270443ae25", "type": "topic", "title": "Archaeological Science, Conservation, and Laboratory Methods", "description": "Use lab and scientific techniques to study materials, residues, provenance, preservation, and the long-term care of archaeological collections.", "children": [{"id": "8cac18aa-374d-4d03-a6e5-c0006159c425", "type": "subtopic", "title": "Compositional and microscopic analysis", "children": [{"id": "0b406d11-22e0-49af-87ae-5059ebed8d9d", "type": "concept", "title": "Petrography, XRF, ICP-MS, SEM, thin sections, and microCT basics"}, {"id": "83fa0c2d-8d85-493f-bb5e-9d754eec6f91", "type": "concept", "title": "Residue, lipid, starch, phytolith, protein, and microbotanical analysis"}, {"id": "e7255cad-13d1-404b-b12b-bd5801b42e65", "type": "concept", "title": "Use-wear, manufacturing traces, and experimental reference collections"}], "description": "Students learn how microscopes and instruments reveal production, use, trade, and material change invisible to the naked eye."}, {"id": "b28a8420-d940-41e0-a220-64e21b66ff9e", "type": "subtopic", "title": "Conservation and collections care", "children": [{"id": "a1e875d7-d180-46e1-9536-410843ab0ca5", "type": "concept", "title": "Cleaning, stabilization, conservation triage, and minimal intervention"}, {"id": "87186bda-b390-4c6d-83d6-ec32533462f2", "type": "concept", "title": "Storage environments, labeling, cataloging, photography, and database records"}, {"id": "014ce3ec-7071-47c0-96a5-cf1a858a3201", "type": "concept", "title": "Legacy collections, rehousing, sampling permissions, and access"}], "description": "This subtopic explains how artifacts must be stabilized, documented, stored, and interpreted without compromising future research."}, {"id": "aa769769-6cc5-4d68-81e7-0de19106d88b", "type": "subtopic", "title": "Experimental and replicative archaeology", "children": [{"id": "f7b699c4-058e-4c7d-9a5e-d0933502736e", "type": "concept", "title": "Replication, experimental design, controls, variables, and documentation"}, {"id": "630c468c-1309-4f52-bcb7-eeb3de8d693d", "type": "concept", "title": "Tool production, firing, cooking, wear, breakage, and deposition experiments"}, {"id": "da6a010d-99c2-46a2-baa4-21a34a94efb3", "type": "concept", "title": "Limits of analogy and communicating experimental uncertainty"}], "description": "Students use controlled making and testing to better understand ancient technologies and behavioral possibilities."}]}, {"id": "2f2cf03e-d564-4789-8bf9-52e5d276819e", "type": "topic", "title": "Social Archaeology: Households, Gender, Identity, Inequality, Ritual, and Power", "description": "Interpret material evidence as part of lived social worlds shaped by labor, status, identity, belief, conflict, and political authority.", "children": [{"id": "f7613ad4-f04e-4670-aa87-22dfc2a15efd", "type": "subtopic", "title": "Households, communities, and daily life", "children": [{"id": "132617a3-d929-4042-8dcd-9a06450cf215", "type": "concept", "title": "Activity areas, food preparation, craft production, storage, and refuse"}, {"id": "42bf8607-8334-4f9b-8814-0f073e839f6d", "type": "concept", "title": "Household archaeology, neighborhoods, settlement pattern, and community organization"}, {"id": "7c044484-d15f-473e-861e-27640ff6d432", "type": "concept", "title": "Childhood, aging, care, disability, and life-course approaches"}], "description": "Students learn to see ordinary spaces and objects as evidence for social relations, labor, care, and everyday practice."}, {"id": "4c3c737b-abde-4c45-afce-be198d8425b0", "type": "subtopic", "title": "Gender, identity, and inequality", "children": [{"id": "c1be5c3d-9cba-48ed-b637-30c66e9cd890", "type": "concept", "title": "Gender archaeology, intersectionality, personhood, embodiment, and dress"}, {"id": "c3bfd0a3-1330-41a2-9fec-852d64edc2a3", "type": "concept", "title": "Status, class, slavery, labor, colonial categories, and racialization"}, {"id": "bff3c1d3-ddda-4e2d-a04d-30b7bc9f7dce", "type": "concept", "title": "Burials, domestic space, craft, diet, mobility, and material display"}], "description": "This subtopic develops methods for studying social difference without projecting modern assumptions uncritically onto the past."}, {"id": "8a0991fe-a06d-4066-9bdc-e0d152c41e5e", "type": "subtopic", "title": "Ritual, ideology, violence, and power", "children": [{"id": "4784875c-77cf-43b9-ab0b-598c19b334b1", "type": "concept", "title": "Sacred landscapes, offerings, temples, pilgrimage, and mortuary practice"}, {"id": "3a9996f9-4671-48d2-8fa5-236e15d4b312", "type": "concept", "title": "Warfare, fortification, trauma, captivity, and political control"}, {"id": "17efe566-f7c6-4b43-8b4c-8edfeafd127f", "type": "concept", "title": "Chiefdoms, states, empires, resistance, and collapse debates"}], "description": "Students examine how material remains reveal belief systems, conflict, political authority, and social negotiation."}]}, {"id": "e7a60cd3-6146-4ce2-a671-894cbc4b1a2c", "type": "topic", "title": "Origins and Transformations: Human Evolution, Agriculture, Urbanism, States, and Empires", "description": "Use major global transformations as laboratories for comparing evidence, causation, adaptation, inequality, and long-term consequence.", "children": [{"id": "51f91f39-02de-4549-9a48-e3f3fb12ffa5", "type": "subtopic", "title": "Human origins and dispersals", "children": [{"id": "62f47f45-bbaa-4d37-8be4-9b89828655e1", "type": "concept", "title": "Stone tool traditions, fire, shelters, symbolic behavior, and mobility"}, {"id": "513046ef-8d63-4269-b227-f0633e9ac53a", "type": "concept", "title": "Out-of-Africa models, regional evidence, and modern human behavior debates"}, {"id": "74923a3d-3354-4b74-af54-3e65f782269f", "type": "concept", "title": "Neanderthals, Denisovans, Homo sapiens, interaction, and admixture"}], "description": "Students connect archaeological evidence with fossil, genetic, environmental, and behavioral data about human evolution."}, {"id": "c0990f94-1e33-45d0-a384-69153f612a83", "type": "subtopic", "title": "Domestication and agricultural transitions", "children": [{"id": "58f1dbfa-2992-41db-a29c-74fa2dc9e5ab", "type": "concept", "title": "Centers of domestication, niche construction, intensification, and risk"}, {"id": "ee0af9f0-0261-411f-b581-a45cbfc8b75c", "type": "concept", "title": "Sedentism, storage, demographic change, disease, and labor"}, {"id": "fb132b64-2579-43e1-85b6-f71b0f15e1d8", "type": "concept", "title": "Regional pathways in Southwest Asia, East Asia, Africa, the Americas, and Oceania"}], "description": "This subtopic asks why and how people shifted toward cultivation, herding, settlement, and new relationships with plants and animals."}, {"id": "7c8045db-2141-4bba-914e-769bdd233da8", "type": "subtopic", "title": "Urbanism, states, and empires", "children": [{"id": "9cae7e68-83da-461a-9d9b-844f3f26c916", "type": "concept", "title": "Cities, infrastructure, writing, administration, craft, and trade"}, {"id": "acd94ca8-e2ad-4f03-977f-27f6e3af8bea", "type": "concept", "title": "Power, inequality, taxation, monumentality, and ideology"}, {"id": "7ea3951c-d757-4ff6-8846-813d1b3d3447", "type": "concept", "title": "Collapse, resilience, migration, conquest, and imperial frontiers"}], "description": "Students compare the emergence of cities and political complexity without treating hierarchy as a single universal script."}]}, {"id": "1eccd531-27c2-412d-ac8e-58c1c0b57422", "type": "topic", "title": "Public Archaeology, Museums, Community Collaboration, and Interpretation", "description": "Translate archaeological knowledge for public audiences while respecting community authority, heritage values, and contested memory.", "children": [{"id": "83d2c86c-cd8b-40ed-b745-0974b0d1f063", "type": "subtopic", "title": "Public archaeology and outreach", "children": [{"id": "5f048427-8023-4b43-83c6-58a5020a1e80", "type": "concept", "title": "Audience analysis, interpretive goals, story structure, and accessibility"}, {"id": "37aa511c-4755-4d81-91d4-9570d83740b7", "type": "concept", "title": "Combating pseudoarchaeology, misinformation, and sensationalism"}, {"id": "facd6f17-dd51-4c13-b61b-e27eb0576cfb", "type": "concept", "title": "Citizen science, volunteer programs, site stewardship, and public trust"}], "description": "Students learn how archaeological interpretation reaches classrooms, media, public talks, site tours, and digital audiences."}, {"id": "0803045b-18d6-4c48-bedc-93692e724760", "type": "subtopic", "title": "Museums, exhibitions, and collections interpretation", "children": [{"id": "ec66a97e-0d7e-4c94-9532-5509a3287c12", "type": "concept", "title": "Exhibit labels, object biographies, interpretive planning, and visitor learning"}, {"id": "a0940c01-0b9a-4125-b94a-a4682d5e85c2", "type": "concept", "title": "Provenance, repatriation, contested display, and community curation"}, {"id": "098c36b6-6f25-4347-a95f-3aad350c1aa4", "type": "concept", "title": "Digital collections, 3D models, metadata, and open educational resources"}], "description": "This subtopic draws from public history and museum studies to present objects in ways that are accurate, ethical, and engaging."}, {"id": "eba5710e-2a73-4142-8f48-4bd0004eee65", "type": "subtopic", "title": "Community collaboration and descendant engagement", "children": [{"id": "86c1da47-9cec-4d0e-83eb-669b9b1d9492", "type": "concept", "title": "Consultation, co-design, memoranda of understanding, and shared governance"}, {"id": "dfbc5843-2ae8-4ff2-9da4-f78c69c3e2fe", "type": "concept", "title": "Return of findings, local benefit, language access, and long-term accountability"}, {"id": "eb7c2b6e-31cb-498b-aef3-ba3338854f8c", "type": "concept", "title": "Indigenous archaeology, community archaeology, and participatory interpretation"}], "description": "Students practice archaeology as relationship-building, not simply data extraction."}]}, {"id": "48ab7af9-2b21-4fa5-947c-9508222ab08b", "type": "topic", "title": "Cultural Resource Management, Compliance, Impact Assessment, and Professional Practice", "description": "Prepare students for applied archaeology in American CRM, environmental review, development contexts, and professional field careers.", "children": [{"id": "398546fc-2065-4474-9d55-d476013b94ed", "type": "subtopic", "title": "CRM workflow and legal compliance", "children": [{"id": "534e820d-e49d-429f-8e27-8d9fdbf3266e", "type": "concept", "title": "Phase I survey, Phase II evaluation, Phase III mitigation, and reporting"}, {"id": "bc78392c-e6bd-4a1c-a0d9-f958bcd7e890", "type": "concept", "title": "Eligibility, significance, integrity, National Register criteria, and avoidance"}, {"id": "32816051-4b18-4ea7-b073-2532bde0bcd2", "type": "concept", "title": "SHPO/THPO roles, Section 106 review, NEPA interfaces, and memoranda of agreement"}], "description": "Students learn how archaeology operates in infrastructure, land management, tribal consultation, and preservation decision-making."}, {"id": "81170c95-2127-43a1-a1ac-4817a100af91", "type": "subtopic", "title": "Impact assessment and site management", "children": [{"id": "a5474454-0dc2-4540-870b-5d0b3143383f", "type": "concept", "title": "Area of potential effects, predictive modeling, construction monitoring, and inadvertent discoveries"}, {"id": "de1ea9e6-6cf4-439f-b720-f568581dabb1", "type": "concept", "title": "Management plans, conservation easements, site stabilization, and climate threats"}, {"id": "f7aa3a6c-2f1f-44a1-8c9c-d6faf314365b", "type": "concept", "title": "Balancing research value, community value, development pressure, and legal requirements"}], "description": "This subtopic focuses on practical decisions about preservation, excavation, monitoring, and long-term stewardship."}, {"id": "de0ce4ee-18b0-4cb5-9f92-97153fce7265", "type": "subtopic", "title": "Professional skills and field safety", "children": [{"id": "d8d809e3-a45b-45ac-885d-34ee79a6370a", "type": "concept", "title": "Field safety, crew communication, equipment, logistics, and daily workflow"}, {"id": "29e05ee1-e7ae-47bb-960c-a33fbd034614", "type": "concept", "title": "Technical writing, maps, forms, photo logs, artifact processing, and QA/QC"}, {"id": "4010edeb-04b8-4e7f-96b5-fe401591955a", "type": "concept", "title": "Resumes, field school selection, professional networks, and ethical employment"}], "description": "Students develop the workplace habits expected of cultural resource technicians, field archaeologists, and project staff."}]}, {"id": "1afa7b0c-7031-4858-b40b-bdb2f72c0de7", "type": "topic", "title": "Digital Archaeology, Data Management, Reproducibility, and Open Science", "description": "Use digital tools responsibly to record, analyze, preserve, share, and critique archaeological data.", "children": [{"id": "f2226934-fd3c-442b-bfbf-f4f7dc138820", "type": "subtopic", "title": "Databases, metadata, and archaeological archives", "children": [{"id": "2dfb0c4d-f8de-419c-91f7-a65396053176", "type": "concept", "title": "Catalog structures, controlled vocabularies, provenience fields, and persistent identifiers"}, {"id": "27b4791f-5bec-488c-a931-3724abd471c5", "type": "concept", "title": "Metadata standards, paradata, codebooks, and archival deposit"}, {"id": "8c41f82a-ff0b-46bb-b59d-d1efa44d51ba", "type": "concept", "title": "Digital Archaeological Record, Archaeology Data Service, and Open Context models"}], "description": "Students learn that archaeological data must remain interpretable beyond the original project team."}, {"id": "b40249d6-be1e-424b-8669-3dfd2d25d8be", "type": "subtopic", "title": "Digital analysis and visualization", "children": [{"id": "a235bbdb-c8f9-49a2-84cf-164fb7cfd49b", "type": "concept", "title": "GIS, network analysis, spatial statistics, photogrammetry, 3D modeling, and dashboards"}, {"id": "ff9e27a8-cb60-4bc9-bc4a-79a40cd7f3e8", "type": "concept", "title": "Remote collaboration, version control, notebooks, and reproducible workflows"}, {"id": "5790fa2a-8bea-46dd-abdd-9bc381440d5b", "type": "concept", "title": "Visualization ethics, uncertainty, missing data, and accessible design"}], "description": "This subtopic introduces tools for exploring archaeological patterns while maintaining interpretive humility."}, {"id": "66352daa-dcb3-400e-978d-9af7f6dee867", "type": "subtopic", "title": "Open science, privacy, and data sovereignty", "children": [{"id": "78f05173-b864-46c5-9779-3cc79d9d2fc9", "type": "concept", "title": "FAIR data principles, licenses, repositories, and citation"}, {"id": "8555d5b8-121e-4049-915e-98a34465f4da", "type": "concept", "title": "Sensitive site locations, looting risk, human remains, and community permissions"}, {"id": "6e97b9ce-f77c-4918-b978-799a32cf6b7b", "type": "concept", "title": "CARE principles, Indigenous data governance, and responsible reuse"}], "description": "Students evaluate when openness helps scholarship and when restriction protects sites, communities, and sacred knowledge."}]}, {"id": "e71fb1f8-3e7e-4298-a381-f0b4fc10ef0a", "type": "topic", "title": "Archaeology Capstone: Research Proposal, Site Report, and Public Communication", "description": "Synthesize theory, method, ethics, analysis, and communication through a polished archaeological research product.", "children": [{"id": "20e6d833-4681-4fab-9ae4-c03408c322f6", "type": "subtopic", "title": "Research proposal or site report", "children": [{"id": "a49fabf6-76b3-4c8b-b835-d043d3bc6c06", "type": "concept", "title": "Background, literature review, research questions, methods, expected evidence, and limitations"}, {"id": "aacd77e6-6f38-43d0-b346-a4b2176a8e24", "type": "concept", "title": "Results, artifact tables, maps, figures, appendices, and management recommendations"}, {"id": "f0a3ac64-61d5-4f30-9210-ffbcacfc967a", "type": "concept", "title": "Clear claims, transparent uncertainty, and responsible citation"}], "description": "Students practice the genre conventions of professional archaeological writing from question to evidence to defensible interpretation."}, {"id": "b7d09cb1-b27b-42e9-a749-704ccc0e9180", "type": "subtopic", "title": "Integrated analysis", "children": [{"id": "2b3f0e6f-f0a9-4b86-8edc-4daf5fc4739f", "type": "concept", "title": "Linking stratigraphy, dating, artifacts, environmental data, and spatial analysis"}, {"id": "1c6feaa7-0bf3-43e8-b26b-1760a6ce88c8", "type": "concept", "title": "Comparing alternative explanations and ruling out weak interpretations"}, {"id": "788f99e6-e3f4-469d-88a0-6f94d6955787", "type": "concept", "title": "Connecting site-level findings to regional, theoretical, and public questions"}], "description": "This subtopic asks students to combine multiple evidence streams instead of treating methods as isolated techniques."}, {"id": "898ce950-b617-473d-b39b-47b573ef3d1f", "type": "subtopic", "title": "Public communication and reflection", "children": [{"id": "4f1e3b79-72a7-419f-9267-17c3e2676e06", "type": "concept", "title": "Public abstract, exhibit label, story map, poster, or short presentation"}, {"id": "6b486558-1222-43f5-b1f4-675c6969d5d9", "type": "concept", "title": "Plain-language writing, visuals, accessibility, and audience needs"}, {"id": "86410278-5700-4a08-9868-7fff51003f56", "type": "concept", "title": "Ethical reflection, collaboration record, and next-step recommendations"}], "description": "Students finish by translating research for non-specialist audiences and reflecting on responsibility, positionality, and future work."}]}], "dbBacked": true}$archjson$::jsonb,
